INSERT INTO `wp_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `icon`, `is_read`) VALUES
(1,	'stripe_applepay_holiday2021',	'marketing',	'en_US',	'Boost sales this holiday season with Apple Pay!',	'Increase your conversion rate by letting your customers know that you accept Apple Pay. It’s seamless to <a href=\"https://docs.woocommerce.com/document/stripe/?_ga=2.90941597.642705274.1635776464-1391993999.1621950839#apple-pay\">enable Apple Pay with Stripe</a> and easy to communicate it with this <a href=\"https://developer.apple.com/apple-pay/marketing/\">marketing guide</a>.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:22',	NULL,	0,	'plain',	'',	0,	'info',	1),
(2,	'square_applepay_holiday2021',	'marketing',	'en_US',	'Boost sales this holiday season with Apple Pay!',	'Increase your conversion rate by letting your customers know that you accept Apple Pay. It’s seamless to <a href=\"https://docs.woocommerce.com/document/woocommerce-square/?_ga=2.90941597.642705274.1635776464-1391993999.1621950839#section-14\">enable Apple Pay with Square</a> and easy to communicate it with this <a href=\"https://developer.apple.com/apple-pay/marketing/\">marketing guide</a>.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:22',	NULL,	0,	'plain',	'',	0,	'info',	1),
(3,	'wcpay_applepay_holiday2021',	'marketing',	'en_US',	'Boost sales this holiday season with Apple Pay!',	'Increase your conversion rate by letting your customers know that you accept Apple Pay. It’s seamless to <a href=\"https://docs.woocommerce.com/document/payments/apple-pay/\">enable Apple Pay with WooCommerce Payments</a> and easy to communicate it with this <a href=\"https://developer.apple.com/apple-pay/marketing/\">marketing guide</a>.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:23',	NULL,	0,	'plain',	'',	0,	'info',	1),
(4,	'new_in_app_marketplace_2021',	'info',	'en_US',	'Customize your store with extensions',	'Check out our NEW Extensions tab to see our favorite extensions for customizing your store, and discover the most popular extensions in the WooCommerce Marketplace.',	'{}',	'unactioned',	'woocommerce.com',	'2021-11-29 20:05:23',	NULL,	0,	'plain',	'',	1,	'info',	1),
(5,	'wayflyer_bnpl_q4_2021',	'marketing',	'en_US',	'Grow your business with funding through Wayflyer',	'Fast, flexible financing to boost cash flow and help your business grow – one fee, no interest rates, penalties, equity, or personal guarantees. Based on your store’s performance, Wayflyer provides funding and analytical insights to invest in your business.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:23',	NULL,	0,	'plain',	'',	0,	'info',	1),
(6,	'wc_shipping_mobile_app_usps_q4_2021',	'marketing',	'en_US',	'Print and manage your shipping labels with WooCommerce Shipping and the WooCommerce Mobile App',	'Save time by printing, purchasing, refunding, and tracking shipping labels generated by <a href=\"https://woocommerce.com/woocommerce-shipping/\">WooCommerce Shipping</a> – all directly from your mobile device!',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:23',	NULL,	0,	'plain',	'',	0,	'info',	1),
(7,	'wc_shipping_mobile_app_q4_2021',	'marketing',	'en_US',	'Print and manage your shipping labels with the WooCommerce Mobile App',	'Save time by printing, purchasing, refunding, and tracking shipping labels generated by <a href=\"https://woocommerce.com/woocommerce-shipping/\">WooCommerce Shipping</a> – all directly from your mobile device!',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(8,	'ecomm-need-help-setting-up-your-store',	'info',	'en_US',	'Need help setting up your Store?',	'Schedule a free 30-min <a href=\"https://wordpress.com/support/concierge-support/\">quick start session</a> and get help from our specialists. We’re happy to walk through setup steps, show you around the WordPress.com dashboard, troubleshoot any issues you may have, and help you the find the features you need to accomplish your goals for your site.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(9,	'woocommerce-services',	'info',	'en_US',	'WooCommerce Shipping & Tax',	'WooCommerce Shipping &amp; Tax helps get your store \"ready to sell\" as quickly as possible. You create your products. We take care of tax calculation, payment processing, and shipping label printing! Learn more about the extension that you just installed.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(10,	'ecomm-unique-shopping-experience',	'info',	'en_US',	'For a shopping experience as unique as your customers',	'Product Add-Ons allow your customers to personalize products while they’re shopping on your online store. No more follow-up email requests—customers get what they want, before they’re done checking out. Learn more about this extension that comes included in your plan.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(11,	'wc-admin-getting-started-in-ecommerce',	'info',	'en_US',	'Getting Started in eCommerce - webinar',	'We want to make eCommerce and this process of getting started as easy as possible for you. Watch this webinar to get tips on how to have our store up and running in a breeze.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:25',	NULL,	0,	'plain',	'',	0,	'info',	1),
(12,	'your-first-product',	'info',	'en_US',	'Your first product',	'That’s huge! You’re well on your way to building a successful online store — now it’s time to think about how you’ll fulfill your orders.<br /><br />Read our shipping guide to learn best practices and options for putting together your shipping strategy. And for WooCommerce stores in the United States, you can print discounted shipping labels via USPS with <a href=\"https://href.li/?https://woocommerce.com/shipping\" target=\"_blank\">WooCommerce Shipping</a>.',	'{}',	'unactioned',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	1,	'info',	1),
(13,	'wc-admin-optimizing-the-checkout-flow',	'info',	'en_US',	'Optimizing the checkout flow',	'It’s crucial to get your store’s checkout as smooth as possible to avoid losing sales. Let’s take a look at how you can optimize the checkout experience for your shoppers.',	'{}',	'unactioned',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	1,	'info',	1),
(14,	'wc-admin-first-five-things-to-customize',	'info',	'en_US',	'The first 5 things to customize in your store',	'Deciding what to start with first is tricky. To help you properly prioritize, we\'ve put together this short list of the first few things you should customize in WooCommerce.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:25',	NULL,	0,	'plain',	'',	0,	'info',	1),
(15,	'wc-payments-qualitative-feedback',	'info',	'en_US',	'WooPayments setup - let us know what you think',	'Congrats on enabling WooPayments for your store. Please share your feedback in this 2 minute survey to help us improve the setup process.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:25',	NULL,	0,	'plain',	'',	0,	'info',	1),
(16,	'share-your-feedback-on-paypal',	'info',	'en_US',	'Share your feedback on PayPal',	'Share your feedback in this 2 minute survey about how we can make the process of accepting payments more useful for your store.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:26',	NULL,	0,	'plain',	'',	0,	'info',	1),
(17,	'google_listings_and_ads_install',	'marketing',	'en_US',	'Drive traffic and sales with Google',	'Reach online shoppers to drive traffic and sales for your store by showcasing products across Google, for free or with ads.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:26',	NULL,	0,	'plain',	'',	0,	'info',	1),
(18,	'wc-subscriptions-security-update-3-0-15',	'info',	'en_US',	'WooCommerce Subscriptions security update!',	'We recently released an important security update to WooCommerce Subscriptions. To ensure your site’s data is protected, please upgrade <strong>WooCommerce Subscriptions to version 3.0.15</strong> or later.<br /><br />Click the button below to view and update to the latest Subscriptions version, or log in to <a href=\"https://woocommerce.com/my-dashboard\">WooCommerce.com Dashboard</a> and navigate to your <strong>Downloads</strong> page.<br /><br />We recommend always using the latest version of WooCommerce Subscriptions, and other software running on your site, to ensure maximum security.<br /><br />If you have any questions we are here to help — just <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">open a ticket</a>.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:26',	NULL,	0,	'plain',	'',	0,	'info',	1),
(19,	'woocommerce-core-update-5-4-0',	'info',	'en_US',	'Update to WooCommerce 5.4.1 now',	'WooCommerce 5.4.1 addresses a checkout issue discovered in WooCommerce 5.4. We recommend upgrading to WooCommerce 5.4.1 as soon as possible.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:26',	NULL,	0,	'plain',	'',	0,	'info',	1),
(20,	'wcpay-promo-2020-11',	'marketing',	'en_US',	'wcpay-promo-2020-11',	'wcpay-promo-2020-11',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:27',	NULL,	0,	'plain',	'',	0,	'info',	1),
(21,	'wcpay-promo-2020-12',	'marketing',	'en_US',	'wcpay-promo-2020-12',	'wcpay-promo-2020-12',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:27',	NULL,	0,	'plain',	'',	0,	'info',	1),
(22,	'wcpay-promo-2021-6-incentive-1',	'marketing',	'en_US',	'Simplify the payments process for you and your customers with WooCommerce Payments',	'With <a href=\"https://woocommerce.com/payments/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">WooCommerce Payments</a>, you can securely accept all major cards, Apple Pay®, and recurring revenue in over 100 currencies.\n				Built into your store’s WooCommerce dashboard, track cash flow and manage all of your transactions in one place – with no setup costs or monthly fees.\n				<br /><br />\n				By clicking \"Get WooCommerce Payments,\" you agree to the <a href=\"https://wordpress.com/tos/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">Terms of Service</a>\n				and acknowledge you have read the <a href=\"https://automattic.com/privacy/\">Privacy Policy</a>.\n				',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:27',	NULL,	0,	'plain',	'',	0,	'info',	1),
(23,	'wcpay-promo-2021-6-incentive-2',	'marketing',	'en_US',	'Simplify the payments process for you and your customers with WooCommerce Payments',	'With <a href=\"https://woocommerce.com/payments/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">WooCommerce Payments</a>, you can securely accept all major cards, Apple Pay®, and recurring revenue in over 100 currencies.\n				Built into your store’s WooCommerce dashboard, track cash flow and manage all of your transactions in one place – with no setup costs or monthly fees.\n				<br /><br />\n				By clicking \"Get WooCommerce Payments,\" you agree to the <a href=\"https://wordpress.com/tos/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">Terms of Service</a>\n				and acknowledge you have read the <a href=\"https://automattic.com/privacy/\">Privacy Policy</a>.\n				',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:27',	NULL,	0,	'plain',	'',	0,	'info',	1),
(24,	'ppxo-pps-upgrade-paypal-payments-1',	'info',	'en_US',	'Get the latest PayPal extension for WooCommerce',	'Heads up! There’s a new PayPal on the block!<br /><br />Now is a great time to upgrade to our latest <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal extension</a> to continue to receive support and updates with PayPal.<br /><br />Get access to a full suite of PayPal payment methods, extensive currency and country coverage, and pay later options with the all-new PayPal extension for WooCommerce.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:27',	NULL,	0,	'plain',	'',	0,	'info',	1),
(25,	'ppxo-pps-upgrade-paypal-payments-2',	'info',	'en_US',	'Upgrade your PayPal experience!',	'Get access to a full suite of PayPal payment methods, extensive currency and country coverage, offer subscription and recurring payments, and the new PayPal pay later options.<br /><br />Start using our <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">latest PayPal today</a> to continue to receive support and updates.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:27',	NULL,	0,	'plain',	'',	0,	'info',	1),
(26,	'woocommerce-core-sqli-july-2021-need-to-update',	'update',	'en_US',	'Action required: Critical vulnerabilities in WooCommerce',	'In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:28',	NULL,	0,	'plain',	'',	0,	'info',	1),
(27,	'woocommerce-blocks-sqli-july-2021-need-to-update',	'update',	'en_US',	'Action required: Critical vulnerabilities in WooCommerce Blocks',	'In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:29',	NULL,	0,	'plain',	'',	0,	'info',	1),
(28,	'woocommerce-core-sqli-july-2021-store-patched',	'update',	'en_US',	'Solved: Critical vulnerabilities patched in WooCommerce',	'In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:29',	NULL,	0,	'plain',	'',	0,	'info',	1),
(29,	'woocommerce-blocks-sqli-july-2021-store-patched',	'update',	'en_US',	'Solved: Critical vulnerabilities patched in WooCommerce Blocks',	'In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:29',	NULL,	0,	'plain',	'',	0,	'info',	1),
(30,	'habit-moment-survey',	'marketing',	'en_US',	'We’re all ears! Share your experience so far with WooCommerce',	'We’d love your input to shape the future of WooCommerce together. Feel free to share any feedback, ideas or suggestions that you have.',	'{}',	'pending',	'woocommerce.com',	'2021-11-29 20:05:30',	NULL,	0,	'plain',	'',	0,	'info',	1),
(32,	'wc-admin-wc-helper-connection',	'info',	'en_US',	'Connettiti a WooCommerce.com',	'Connettiti per ottenere notifiche e aggiornamenti sui prodotti importanti.',	'{}',	'unactioned',	'woocommerce-admin',	'2021-11-29 20:05:35',	NULL,	0,	'plain',	'',	1,	'info',	1),
(33,	'storefront-customize',	'info',	'en_US',	'Design your store with Storefront 🎨',	'Visit the Storefront settings page to start setup and customization of your shop.',	'{}',	'unactioned',	'storefront',	'2021-11-29 21:05:37',	NULL,	0,	'plain',	'',	1,	'info',	1),
(35,	'wc-admin-test-checkout',	'info',	'en_US',	'Non dimenticare di testare la procedura di acquisto',	'Assicurati che la procedura di acquisto funzioni correttamente prima di lanciare il tuo negozio. Completa la procedura di acquisto nella sua interezza: aggiunta di un prodotto al carrello, scelta di un indirizzo di spedizione ed effettuazione del pagamento.',	'{}',	'unactioned',	'woocommerce-admin',	'2021-11-29 21:58:16',	NULL,	0,	'plain',	'',	1,	'info',	1),
(36,	'woocommerce-core-paypal-march-2022-updated',	'update',	'en_US',	'Security auto-update of WooCommerce',	'<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy PayPal Standard security updates for stores running WooCommerce (version 3.5 to 6.3). It’s recommended to disable PayPal Standard, and use <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal Payments</a> to accept PayPal.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(37,	'woocommerce-core-paypal-march-2022-updated-nopp',	'update',	'en_US',	'Security auto-update of WooCommerce',	'<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy security updates related to PayPal Standard payment gateway for stores running WooCommerce (version 3.5 to 6.3).',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(38,	'pinterest_03_2022_update',	'marketing',	'en_US',	'Your Pinterest for WooCommerce plugin is out of date!',	'Update to the latest version of Pinterest for WooCommerce to continue using this plugin and keep your store connected with Pinterest. To update, visit <strong>Plugins &gt; Installed Plugins</strong>, and click on “update now” under Pinterest for WooCommerce.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(39,	'store_setup_survey_survey_q2_2022',	'survey',	'en_US',	'Come va la configurazione del negozio?',	'Il nostro obiettivo è quello di offrirti tutti gli strumenti giusti per iniziare a configurare il tuo negozio nel modo più semplice possibile.\r\nCi piacerebbe sapere se l\'abbiamo raggiunto e come possiamo migliorare. Abbiamo creato un sondaggio di 2 minuti per conoscere la tua opinione.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(40,	'woocommerce-payments-august-2022-need-to-update',	'update',	'en_US',	'Action required: Please update WooCommerce Payments',	'An updated secure version of WooCommerce Payments is available – please ensure that you’re using the latest patch version. For more information on what action you need to take, please review the article below.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(41,	'woocommerce-payments-august-2022-store-patched',	'update',	'en_US',	'WooCommerce Payments has been automatically updated',	'You’re now running the latest secure version of WooCommerce Payments. We’ve worked with the WordPress Plugins team to deploy a security update to stores running WooCommerce Payments (version 3.9 to 4.5). For further information, please review the article below.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(42,	'needs-update-eway-payment-gateway-rin-2022-12-20',	'update',	'en_US',	'Security vulnerability patched in WooCommerce Eway Gateway',	'In response to a potential vulnerability identified in WooCommerce Eway Gateway versions 3.1.0 to 3.5.0, we’ve worked to deploy security fixes and have released an updated version.\r\nNo external exploits have been detected, but we recommend you update to your latest supported version 3.1.26, 3.2.3, 3.3.1, 3.4.6, or 3.5.1',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(43,	'updated-eway-payment-gateway-rin-2022-12-20',	'update',	'en_US',	'WooCommerce Eway Gateway has been automatically updated',	'Your store is now running the latest secure version of WooCommerce Eway Gateway. We worked with the WordPress Plugins team to deploy a software update to stores running WooCommerce Eway Gateway (versions 3.1.0 to 3.5.0) in response to a security vulnerability that was discovered.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(44,	'ecomm-wc-navigation-survey-2023',	'info',	'en_US',	'Navigating WooCommerce on WordPress.com',	'We are improving the WooCommerce navigation on WordPress.com and would love your help to make it better! Please share your experience with us in this 2-minute survey.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(45,	'woopay-beta-merchantrecruitment-04MAY23',	'info',	'en_US',	'Increase conversions with WooPay — our fastest checkout yet',	'WooPay, a new express checkout feature built into WooCommerce Payments, is now available —and we’re inviting you to be one of the first to try it. \r\n<br><br>\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br><br>\r\nGet started in seconds.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(46,	'woocommerce-wcpay-march-2023-update-needed',	'update',	'en_US',	'Action required: Security update for WooCommerce Payments',	'<strong>Your store requires a security update for WooCommerce Payments</strong>. Please update to the latest version of WooCommerce Payments immediately to address a potential vulnerability discovered on March 22. For more information on how to update, visit this WooCommerce Developer Blog Post.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(47,	'tap_to_pay_iphone_q2_2023_no_wcpay',	'marketing',	'en_US',	'Accept in-person contactless payments on your iPhone',	'Tap to Pay on iPhone and WooCommerce Payments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(48,	'woocommerce-WCPreOrders-april-2023-update-needed',	'update',	'en_US',	'Action required: Security update of WooCommerce Pre-Orders extension',	'<strong>Your store requires a security update for the WooCommerce Pre-Orders extension</strong>. Please update the WooCommerce Pre-Orders extension immediately to address a potential vulnerability discovered on April 11.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(49,	'woopay-beta-merchantrecruitment-update-04MAY23',	'info',	'en_US',	'Increase conversions with WooPay — our fastest checkout yet',	'WooPay, a new express checkout feature built into WooCommerce Payments, is now available — and you’re invited to try it. \r\n<br /><br />\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br /><br />\r\nUpdate WooCommerce Payments to get started.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(50,	'woopay-beta-existingmerchants-noaction-27APR23',	'info',	'en_US',	'WooPay is back!',	'Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed. No action is required on your part.\r\n<br /><br />\r\nYou can now continue boosting conversions by offering your customers a simple, secure way to pay with a single click.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(51,	'woopay-beta-existingmerchants-update-27APR23',	'info',	'en_US',	'WooPay is back!',	'Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed.\r\n<br /><br />\r\n\r\nUpdate to the latest WooCommerce Payments version to continue boosting conversions by offering your customers a simple, secure way to pay with a single click.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
