(62,	'woocommerce-WCSubscriptions-June-2023-updated-needed',	'marketing',	'en_US',	'Action required: Security update of WooCommerce Subscriptions',	'<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(63,	'woocommerce-WCReturnsWarranty-June-2023-updated-needed',	'update',	'en_US',	'Action required: Security update of WooCommerce Returns and Warranty Requests extension',	'<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(64,	'woocommerce-WCOPC-June-2023-updated-needed',	'update',	'en_US',	'Action required: Security update of WooCommerce One Page Checkout',	'<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(65,	'woocommerce-WCGC-July-2023-update-needed',	'update',	'en_US',	'Action required: Security update of WooCommerce GoCardless Extension',	'<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(66,	'woocommerce-shipping-fedex-api-outage-2023-07-16',	'warning',	'en_US',	'Scheduled FedEx API outage — July 2023',	'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(67,	'wcship-2023-07-hazmat-update-needed',	'update',	'en_US',	'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension',	'<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(68,	'woocommerce-WCStripe-Aug-2023-update-needed',	'update',	'en_US',	'Action required: Security update for WooCommerce Stripe plugin',	'<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(69,	'woocommerce-WCStripe-Aug-2023-security-updated',	'update',	'en_US',	'Security update of WooCommerce Stripe plugin',	'<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(70,	'woocommerce-WooPayments-Aug-2023-update-needed',	'update',	'en_US',	'Action required: Security update for WooPayments (WooCommerce Payments) plugin',	'<strong>Your shop requires an important security update for the WooPayments (WooCommerce Payments) extension</strong>. The fix for this vulnerability was released on July 31. Please update immediately.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(71,	'woocommerce-WooPayments-Aug-2023-security-updated',	'update',	'en_US',	'Security update of WooPayments (WooCommerce Payments) plugin',	'<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(72,	'avalara_q3-2023_noAvaTax',	'marketing',	'en_US',	'Automatically calculate VAT in real time',	'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(73,	'woo-activation-survey-blockers-22AUG23',	'info',	'en_US',	'How can we help you get that first sale?',	'Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(74,	'woocommerce-usermeta-Sept2023-productvendors',	'update',	'en_US',	'Your store requires a security update',	'<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(75,	'woocommerce-STRIPE-Oct-2023-update-needed',	'update',	'en_US',	'Action required: Security update for WooCommerce Stripe Gateway',	'<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(76,	'amazon-mcf-reviews-2023-12-07',	'marketing',	'en_US',	'Enjoying Amazon MCF for WooCommerce?',	'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!',	'{}',	'pending',	'woocommerce.com',	'2024-01-02 10:30:24',	NULL,	0,	'plain',	'',	0,	'info',	1),
(77,	'wc-admin-launch-checklist',	'info',	'en_US',	'Ready to launch your store?',	'To make sure you never get that sinking \"what did I forget\" feeling, we\'ve put together the essential pre-launch checklist.',	'{}',	'unactioned',	'woocommerce-admin',	'2024-01-02 10:30:32',	NULL,	0,	'plain',	'',	1,	'info',	1),
(78,	'wc-admin-edit-products-on-the-move',	'info',	'en_US',	'Edit products on the move',	'Edit and create new products from your mobile devices with the Woo app',	'{}',	'unactioned',	'woocommerce-admin',	'2024-01-02 10:30:32',	NULL,	0,	'plain',	'',	1,	'info',	1),
(79,	'wc-admin-performance-on-mobile',	'info',	'en_US',	'Track your store performance on mobile',	'Monitor your sales and high performing products with the Woo app.',	'{}',	'unactioned',	'woocommerce-admin',	'2024-01-02 10:30:32',	NULL,	0,	'plain',	'',	1,	'info',	1),
(80,	'wc-admin-manage-orders-on-the-go',	'info',	'en_US',	'Manage your orders on the go',	'Look for orders, customer info, and process refunds in one click with the Woo app.',	'{}',	'unactioned',	'woocommerce-admin',	'2024-01-02 10:30:32',	NULL,	0,	'plain',	'',	1,	'info',	1),
(82,	'wc-update-db-reminder',	'update',	'en_US',	'Aggiornamento database WooCommerce completato',	'Aggiornamento del database di WooCommerce completato. Grazie per aver aggiornato all\'ultima versione!',	'{}',	'actioned',	'woocommerce-core',	'2024-01-02 10:31:05',	NULL,	0,	'plain',	'',	0,	'info',	1),
(83,	'amazon_pay_reactivate_q1-24',	'marketing',	'en_US',	'Special offer: Activate 0% promo rate for Amazon Pay',	'For a limited time, Woo merchants who register with Amazon Pay can enjoy a promotional rate of 0% on all transaction fees for 30 days. Valid for businesses based in the United Kingdom. Terms and conditions apply.',	'{}',	'pending',	'woocommerce.com',	'2024-01-10 08:11:02',	NULL,	0,	'plain',	'',	0,	'info',	0),
(84,	'remove_estimated_deposits_2024',	'marketing',	'en_US',	'Estimated deposits are going away',	'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.',	'{}',	'pending',	'woocommerce.com',	'2024-01-29 10:59:53',	NULL,	0,	'plain',	'',	0,	'info',	0),
(85,	'wc-admin-coupon-page-moved',	'update',	'en_US',	'La gestione dei codici promozionali è stata spostata!',	'I codici promozionali possono ora essere gestiti da Marketing &gt; Codici promozionali. Fai clic sul pulsante di seguito per rimuovere l\'elemento del menu WooCommerce &gt; Codici promozionali legacy.',	'{}',	'actioned',	'woocommerce-admin',	'2024-01-29 11:05:00',	NULL,	0,	'plain',	'',	0,	'info',	1),
(86,	'custom_order_attribution_inbox_q1_2024',	'marketing',	'en_US',	'NEW: Custom Order Attribution',	'Order attribution tracking is now available for all Woo stores! See whether an order came from a search ad, video, or email. Make better marketing decisions and watch your products go from “maybe” to “must-have.”',	'{}',	'pending',	'woocommerce.com',	'2024-02-14 14:28:13',	NULL,	0,	'plain',	'',	0,	'info',	0),
(87,	'wc_admin_UKpricingchange_WCPay_Q1_2024',	'marketing',	'en_US',	'Fee Changes for WooPayments in the EEA and UK',	'WooPayments fees for transactions between the EEA and UK will change as of 1st March, 2024. Transactions between the UK and EEA are now deemed by card networks to be cross-border, thus international payment fees will be applicable. This also changes base processing fees.',	'{}',	'pending',	'woocommerce.com',	'2024-03-06 08:52:50',	NULL,	0,	'plain',	'',	0,	'info',	0),
(88,	'airwallex_q1_2024',	'marketing',	'en_US',	'Save big on foreign exchange (FX) fees',	'Boost your international sales by offering Apple Pay, Google Pay, and 60+ local payment methods with Airwallex. Save time and money by settling payments directly in USD, EUR, HKD, SGD, AUD, and more — without the extra FX fees. Simple, cost-effective, fast.',	'{}',	'unactioned',	'woocommerce.com',	'2024-03-06 08:52:50',	NULL,	0,	'plain',	'',	0,	'info',	0),
(89,	'sirt-woo-2024-11-xss-admin',	'update',	'en_US',	'An important update is required for WooCommerce',	'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>',	'{}',	'pending',	'woocommerce.com',	'2026-01-08 08:03:21',	NULL,	0,	'plain',	'',	0,	'info',	0),
(90,	'paypal-braintree-sdk-depreciation-2025-02-20',	'update',	'en_US',	'Update required for your PayPal Braintree extension',	'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.',	'{}',	'pending',	'woocommerce.com',	'2026-01-08 08:03:21',	NULL,	0,	'plain',	'',	0,	'info',	0),
(91,	'uk-vat-notice-2025-04-30',	'warning',	'en_US',	'UK VAT numbers are no longer supported',	'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement',	'{}',	'pending',	'woocommerce.com',	'2026-01-08 08:03:21',	NULL,	0,	'plain',	'',	0,	'info',	0),
(92,	'paypal-braintree-sdk-depreciation-2025-05-30',	'update',	'en_US',	'Action required: Update the PayPal Braintree extension',	'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.',	'{}',	'pending',	'woocommerce.com',	'2026-01-08 08:03:21',	NULL,	0,	'plain',	'',	0,	'info',	0),
(93,	'paypal-carding-recaptcha-dec-25',	'update',	'en_US',	'Activate PayPal fraud management',	'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.',	'{}',	'pending',	'woocommerce.com',	'2026-01-08 08:03:21',	NULL,	0,	'plain',	'',	0,	'info',	0),
(94,	'downloads-sub-Jan2026-RIN',	'marketing',	'en_US',	'WooCommerce Subscription Downloads is now part of WooCommerce Subscriptions',	'WooCommerce Subscriptions now allows you to include simple and variable downloadable products with your subscriptions. Streamline your subscription downloads by updating to the latest version of WooCommerce Subscriptions today.',	'{}',	'pending',	'woocommerce.com',	'2026-01-08 08:03:21',	NULL,	0,	'plain',	'',	0,	'info',	0),
(95,	'wc-admin-email-improvements',	'info',	'en_US',	'Store emails have had an upgrade!',	'We’ve made some exciting improvements to our email templates, including modern, shopper-friendly designs and new customization options. And if you’re using a block theme, you can automatically sync your theme styles! Head to your email settings to explore the new features.',	'{}',	'unactioned',	'woocommerce-admin',	'2026-01-08 08:03:23',	NULL,	0,	'plain',	'',	0,	'info',	1),
(96,	'wc-admin-scheduled-updates-promotion',	'info',	'en_US',	'Analytics now supports scheduled updates',	'This provides improved performance to your store, enable it in Analytics &gt; Settings.',	'{}',	'unactioned',	'woocommerce-admin',	'2026-03-18 10:06:54',	NULL,	0,	'plain',	'',	0,	'info',	1);
